    box.querySelectorAll('[data-pid]').forEach(el => {
        $('select', el).onchange = async (e) => { const x = await api('POST', '/api/resin/printer-bottle', { printer_id: Number(el.dataset.pid), bottle_id: e.target.value ? Number(e.target.value) : null }); x.ok ? toast(t('saved'), 'success') : toast(rErr(x.data), 'error'); };
    });
